// null: not this template; empty: ambiguous, preserve the entire original.
List<String>? _match(String text, List<String> parts) {
  if (!text.startsWith(parts.first) || !text.endsWith(parts.last)) return null;
  var offset = parts.first.length;
  final end = text.length - parts.last.length;
  if (end < offset) return null;
  final values = <String>[];
  for (var index = 1; index < parts.length - 1; index++) {
    final delimiter = parts[index];
    final next = text.indexOf(delimiter, offset);
    if (next < offset || next > end) return null;
    final again = text.indexOf(delimiter, next + 1);
    if (again >= 0 && again <= end) return const [];
    values.add(text.substring(offset, next));
    offset = next + delimiter.length;
  }
  if (offset > end) return null;
  values.add(text.substring(offset, end));
  return values;
}

// Only canonical status fragments, never names, addresses or file content.
String _atom(AppLocalizations s, String text) => switch (text) {
  "unavailable" => s.uiUnavailable1D5EE3,
  "usable" => s.uiUsable829A7C,
  "one-way" => s.uiOneWay5EF4D0,
  "No new relay protocols detected." => s.statusNoNewProtocols,
  "Route info exchange requested." => s.statusRouteExchangeRequested,
  "Route info exchange could not be sent yet." => s.statusRouteExchangePending,
  "known routes" => s.statusKnownRoutes,
  "reachable" => s.statusReachable,
  "unreachable" => s.statusUnreachable,
  "unknown" => s.statusUnknown,
  "stale" => s.statusExpired,
  _ => text,
};
